namespace ghidra.app.plugin.core.functiongraph.graph.layout;



using generic.theme;
using ghidra.app.plugin.core.functiongraph.graph;
using ghidra.framework.options;
using ghidra.util;
using ghidra.util.task;

public class DecompilerNestedLayoutProvider : FGLayoutProviderExtensionPoint {

	private static readonly Icon ICON = new GIcon("icon.plugin.functiongraph.layout.nested.code");
	static readonly string LAYOUT_NAME = "Nested Code Layout";

	/* @Override */
	public FGLayout getFGLayout(FunctionGraph graph, TaskMonitor monitor) {
		DecompilerNestedLayout layout = new DecompilerNestedLayout(graph, LAYOUT_NAME);
		layout.setTaskMonitor(monitor);
		return layout;
	}

	/* @Override */
	public FGLayoutOptions createLayoutOptions(Options options) {
		DNLayoutOptions layoutOptions = new DNLayoutOptions();
		layoutOptions.registerOptions(options);
		return layoutOptions;
	}

	/* @Override */
	public string getLayoutName() {
		return LAYOUT_NAME;
	}

	/* @Override */
	public Icon getActionIcon() {
		return ICON;
	}

	/* @Override */
	public int getPriorityLevel() {
		return 200; // above the others
	}

	/* @Override */
	public HelpLocation getHelpLocation() {
		return new HelpLocation("FunctionGraphPlugin", "Nested_Code_Layout");
	}

}
